# Callers of the settings wrapper 0x6041a1f9, which is what the direct editor hits.
# Read-only. Do not edit this file after it has run.
from pathlib import Path

BASE = 0x60021020
TARGET = 0x6041A1F9
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
n = len(img)


def s32(off):
    v = int.from_bytes(img[off:off + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16(off):
    v = img[off] | (img[off + 1] << 8)
    return v - 0x10000 if v & 0x8000 else v


lines = ['scan-wrapper-r1 target %08x' % TARGET]
count = 0
i = 0
while i < n - 7:
    op = img[i]
    pc = BASE + i
    target = None
    if op == 0xDD and i + 7 <= n:
        target = (pc + s32(i + 1)) & 0xFFFFFFFF
    elif op == 0xCD and i + 5 <= n:
        target = (pc + s16(i + 1)) & 0xFFFFFFFF
    if target == TARGET:
        pre = img[max(0, i - 24):i].hex()
        lines.append('%08x pre %s' % (pc, pre))
        count += 1
    i += 1
lines.append('calls %d' % count)
text = '\n'.join(lines) + '\n'
Path('work/out/scan-wrapper-r1.txt').write_text(text, encoding='utf-8')
print(text)
